// 1. 断言：验证状态码必须是 200，确保请求成功
pm.test("状态码200，登录成功", function () {
    pm.response.to.have.status(200);
});

// 2. 自动提取返回的 Token，并存入环境变量
pm.test("返回了Token字段", function () {
    const res = pm.response.json();
    pm.expect(res).to.have.property("token");
    pm.environment.set("token", res.token);
});

// 1. 断言：响应状态码是200
pm.test("响应状态码为200 OK", function () {
    pm.response.to.have.status(200);
});

// 2. 断言：返回的数据是数组格式
pm.test("返回结果是数组", function () {
    var res = pm.response.json();
    pm.expect(res).to.be.an('array');
});

// 3. 断言：数组里面每一项，都包含 bookingid 字段
pm.test("数组内元素包含bookingid字段", function () {
    var res = pm.response.json();
    if(res.length>0){
        pm.expect(res[0]).to.have.property('bookingid');
    }
});

// 1. 断言状态码200
pm.test("状态码 200 OK", function () {
    pm.response.to.have.status(200);
});

// 2. 断言返回是JSON对象（注意！上个接口是数组，这里是对象！很容易踩坑）
pm.test("返回数据为JSON对象", function () {
    var res = pm.response.json();
    pm.expect(res).to.be.an('object');
});

// 3. 校验必须包含的核心一级字段
pm.test("包含预订基础字段", function () {
    var res = pm.response.json();
    pm.expect(res).to.have.property("firstname");
    pm.expect(res).to.have.property("lastname");
    pm.expect(res).to.have.property("totalprice");
    pm.expect(res).to.have.property("depositpaid");
    pm.expect(res).to.have.property("bookingdates");
});

// 4. 校验bookingdates里面嵌套的日期字段
pm.test("bookingdates包含checkin和checkout", function () {
    var res = pm.response.json();
    pm.expect(res.bookingdates).to.have.property("checkin");
    pm.expect(res.bookingdates).to.have.property("checkout");
});

// 1. 断言状态码200
pm.test("状态码200，创建预订成功", function () {
    pm.response.to.have.status(200);
});

// 2. 响应是JSON对象
pm.test("返回JSON对象", function () {
    var res = pm.response.json();
    pm.expect(res).to.be.an('object');
});

// 3. 校验返回包含bookingid和booking主体
pm.test("返回bookingid和预订信息", function () {
    var res = pm.response.json();
    pm.expect(res).to.have.property("bookingid");
    pm.expect(res).to.have.property("booking");
});

// 4. 校验booking里面核心字段
pm.test("预订信息字段完整", function () {
    var res = pm.response.json();
    var booking = res.booking;
    pm.expect(booking).to.have.property("firstname");
    pm.expect(booking).to.have.property("lastname");
    pm.expect(booking).to.have.property("totalprice");
    pm.expect(booking.bookingdates).to.have.property("checkin");
    pm.expect(booking.bookingdates).to.have.property("checkout");
});

// ✅ 重点：把新生成的bookingid，存入环境变量bookingid
var res = pm.response.json();
pm.environment.set("bookingid", res.bookingid);

// 1. 断言状态码200
pm.test("状态码200，全量修改成功", function () {
    pm.response.to.have.status(200);
});

// 2. 返回是JSON对象
pm.test("返回JSON对象", function () {
    var res = pm.response.json();
    pm.expect(res).to.be.an('object');
});

// 3. 校验修改后新字段
pm.test("数据更新为修改后的值", function () {
    var res = pm.response.json();
    pm.expect(res.firstname).eql("Amy");
    pm.expect(res.lastname).eql("Li");
    pm.expect(res.totalprice).eql(222);
    pm.expect(res.depositpaid).eql(false);
    pm.expect(res.additionalneeds).eql("Dinner");
});

// 4. 校验嵌套日期对象
pm.test("bookingdates日期字段正常", function () {
    var res = pm.response.json();
    pm.expect(res.bookingdates.checkin).eql("2026-12-02");
    pm.expect(res.bookingdates.checkout).eql("2026-12-06");
});

// 1. 断言响应状态码是200
pm.test("响应状态码200", function () {
    pm.response.to.have.status(200);
});

// 2. 返回是JSON对象
pm.test("返回JSON对象", function () {
    var res = pm.response.json();
    pm.expect(res).to.be.an('object');
});

pm.test("备注信息修改成功", function () {
    var res = pm.response.json();
    pm.expect(res.additionalneeds).to.be.a('string'); 
});

// 1. 断言实际状态码是 201（基于它的实际表现）
pm.test("检查状态码是否为 201 Created", function () {
    pm.response.to.have.status(201);
});

// 2. 断言响应文本内容是 "Created"
pm.test("检查返回文本是否为 Created", function () {
    pm.expect(pm.response.text()).to.eql("Created");
});

pm.test("服务健康检查，状态码201", function () {
    pm.response.to.have.status(201);
});
pm.test("返回提示信息正确", function () {
    pm.expect(pm.response.text()).to.eql("Created");
});
